mapper.update:
update voucher
title = #{title}, sub_title = #{subTitle}, rules = #{rules}, min_amount = #{minAmount}, discount_amount = #{discountAmount}, discount_rate = #{discountRate}, stock = #{stock}, receive_begin_time = #{receiveBeginTime}, receive_end_time = #{receiveEndTime}, use_begin_time = #{useBeginTime}, use_end_time = #{useEndTime}, update_time = now()
where id = #{id}

mapper.select:
select * from voucher

    and status = #{voucherPageQueryDTO.status}
    and type = #{voucherPageQueryDTO.type}

order by id asc limit #{begin},#{voucherPageQueryDTO.pageSize}

select count(*) from voucher

    and status = #{status}
    and type = #{type}

select uv.id,uv.voucher_id,uv.status,uv.receive_time,
       v.title,v.sub_title,v.rules,v.type,v.min_amount,v.discount_amount,v.discount_rate,
       v.use_begin_time,v.use_end_time
from user_voucher uv
inner join voucher v on uv.voucher_id = v.id
where uv.user_id = #{userId}
and uv.status = #{userVoucherQueryDTO.status}
and v.type = #{userVoucherQueryDTO.type}
order by uv.id asc
